async function seedCatalog(db, { log = console.log } = {}) {
  const existing = await db.all('SELECT brand, name FROM cigars', []);
  const have = new Set(existing.map(r => `${r.brand.toLowerCase()}|${r.name.toLowerCase()}`));
  let cigars = 0, vitolas = 0;
  for (const c of CATALOG) {
    const key = `${c.brand.toLowerCase()}|${c.name.toLowerCase()}`;
    if (have.has(key)) continue;
    const r = await db.run(
      `INSERT INTO cigars (brand, name, country, wrapper, binder, filler, strength, flavor_notes, description, year_introduced)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?) RETURNING id`,
      [c.brand, c.name, c.country, c.wrapper, c.binder, c.filler, c.strength, JSON.stringify(c.flavor_notes || []), c.description, c.year_introduced || null]
    );
    cigars++;
    for (const vt of c.vitolas || []) {
      await db.run('INSERT INTO vitolas (cigar_id, name, length, ring_gauge, msrp) VALUES (?, ?, ?, ?, ?)',
        [r.lastInsertRowid, vt.name, vt.length, vt.ring_gauge, vt.msrp]);
      vitolas++;
    }
  }
  if (cigars) log(`[catalog] added ${cigars} cigars and ${vitolas} vitolas (${CATALOG.length} in catalog)`);
  return { cigars, vitolas };
}

if (require.main === module) {
  const db = require('./db');
  const { initSchema, runMigrations } = require('./schema');
  (async () => {
    await initSchema();
    await runMigrations();
    console.log(await seedCatalog(db));
    process.exit(0);
  })().catch(err => { console.error(err); process.exit(1); });
}

module.exports = { CATALOG, seedCatalog };
